-- Series 84C-10/20/30 (3-piece cryogenic, quote-only Price NULL). Run from file (SSMS). Self-cleaning on re-run.
IF NOT EXISTS (SELECT 1 FROM Categories WHERE Name = N'Series 84C-10/20/30')
    INSERT INTO Categories (Name, Description, BodyMaterial, SeatMaterial, Design, Approvals, TemperatureRange, KeyFeatures)
    VALUES (N'Series 84C-10/20/30',
        N'The Mars Series 84C-10/20/30 is a 3-piece, full-port cryogenic ball valve with an ISO 5211 mounting pad and a blow-out-proof stem, designed for liquid nitrogen, helium, CO2 and other liquefied gases. Rated -196 to +95 degree C and designed to ASME B16.34 / ISO 17292. CF8M body (Hastelloy C, Alloy 20, Super Duplex, Monel or 254 SMO on request) with TFM4215/PCTFE seats and a Viton stem o-ring, in threaded, socket-weld or butt-weld ends, sizes 1/4" to 4".',
        N'CF8M / Hastelloy C / Alloy 20 / Super Duplex / Monel / 254 SMO', N'TFM4215 / PCTFE', N'Three Piece, Cryogenic, Full Port', N'ASME B16.34; ISO 17292', N'-196 to +95 degree C',
        N'3-piece cryogenic full port design
ISO 5211 mounting pad
Blow-out proof stem
Ends: Threaded, Socket Weld, Butt Weld
Body: CF8M, Hastelloy C, Alloy 20, Super Duplex, Monel, 254 SMO
Seats: TFM4215, PCTFE
Viton o-ring on stem
For liquid nitrogen, helium, CO2 and other liquid gas
Designed to ASME B16.34 / ISO 17292
Temperature range -196 to +95 degree C
Size 1/4" to 4"');

DECLARE @SeriesName nvarchar(100) = N'Series 84C-10/20/30';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);

-- Idempotent: clear any prior rows for this series so re-running always yields a clean set.
DELETE FROM ProductFilterValues WHERE CategoryId = @CategoryId;
DELETE FROM CatalogProducts WHERE CategoryId = @CategoryId;
DELETE FROM CategoryFilters WHERE CategoryId = @CategoryId;

INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'Ends'),(N'Size'),(N'Body'),(N'Seat')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);

INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder FROM (VALUES (N'Ends',0),(N'Size',1),(N'Body',2),(N'Seat',3)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);

